int linear_search(int a[], int n, int x)
{
    int i;
    // har element ko dekho
    for(i = 0; i < n; i++)
    {
        // agar a[i] x ke barabar hai to i return karo
        if(a[i] = x)
        {
            return i;
        }
    }
    return -1;
}
